"use strict";
// SPEC-002-080 AC2: every case of the canonical shared fixture (vendor/agent-file-board/tests/fixtures/subthreads/
// cases.json, generated by canonical boardctl, SPEC-002-079) runs through the viewer, with no skips. Contract (AC2
// amendment, parent ruling 2026-11-03): rule id and verdict for every file, warning, other error and post; exact text
// for the sub-thread rules (subthread.*, also.*, state.*, promoted.*, member.*, orphan.*, repair.* and the reply-target
// rules) wherever `validate` reports them; rule id only for generic file-format errors and for the CLI-worded post
// refusals (member.before-root's "--at" hint, subthread.root-ineligible, promote.*). Membership, the main flow, the
// state, reply count and participants of each sub-thread and the orphans are compared exactly, for the complete set
// and for every recorded arrival order (S4). Boards are real folders opened through the upload input, so exact
// bytes (invalid UTF-8) and modification times are the canonical ones. Owner policy: no VoiceOver checks.
const { test, before, after } = require("node:test");
const assert = require("node:assert/strict");
const h = require("./lib/helpers");

const FIXTURE = h.path.join(h.VENDOR, "tests", "fixtures", "subthreads", "cases.json");
const DATA = JSON.parse(h.fs.readFileSync(FIXTURE, "utf8"));
const ROOM = DATA.board.room;

// Canonical's classifier (scripts/build_subthread_cases.py RULES), plus the viewer's own texts for the rules
// whose wording is the CLI's or Python's (AC2 amendment).
const RULES = [
  [/^SUBTHREAD: expected the filename of a \.txt message/, "subthread.value"],
  [/^PROMOTED-FROM: expected the filename of a \.txt message/, "promoted.value"],
  [/^SUBTHREAD-ALSO: only a sub-thread message/, "also.needs-subthread"],
  [/^SUBTHREAD-ALSO: the only value is main$/, "also.value"],
  [/^SUBTHREAD-STATE: only a sub-thread message/, "state.needs-subthread"],
  [/^SUBTHREAD-STATE: expected resolved or open$/, "state.value"],
  [/^PROMOTED-FROM: a topic's first message cannot also be a sub-thread message$/, "promoted.with-subthread"],
  [/^SUBTHREAD: STATUS CLOSED is invalid on a sub-thread message/, "subthread.closed"],
  [/^SUBTHREAD: root must be a regular file$/, "subthread.root-not-file"],
  [/^SUBTHREAD: root \S+ is in another thread/, "subthread.root-other-thread"],
  [/^SUBTHREAD: root \S+ is itself a sub-thread message; sub-threads nest one level only$/, "subthread.nesting"],
  [/^SUBTHREAD: a sub-thread message must sort after its root/, "member.before-root"],
  [/^SUBTHREAD: root \S+ does not exist in this directory$/, "subthread.root-missing"],
  [/^SUBTHREAD: REPLY-TO must name the root or another message of the same sub-thread, not -$/, "subthread.reply-dash"],
  [/^SUBTHREAD: REPLY-TO target does not exist in this directory$/, "subthread.reply-missing"],
  [/^SUBTHREAD: REPLY-TO \S+ is neither the root/, "subthread.reply-to"],
  [/^SUBTHREAD: an ANSWER to a question inside a sub-thread must carry SUBTHREAD/, "subthread.answer-marker"],
  [/^PROMOTED-FROM: \S+ is not a message in this directory$/, "promoted.origin-missing"],
  [/^PROMOTED-FROM: names a sub-thread message, not a root$/, "promoted.origin-member"],
  [/^PROMOTED-FROM: a promoted sub-thread continues in a new topic/, "promoted.same-topic"],
  [/^PROMOTED-FROM: only the first message of a topic can carry it/, "promoted.not-first"],
  [/^sub-thread root is not eligible under signing requirements/, "subthread.root-ineligible"],
  [/^Sub-thread root excluded by signing requirements$/, "subthread.root-ineligible"],
  [/^REPLY-TO target is missing$/, "reply-to.missing"],
  [/^ANSWER reply target is missing$/, "answer.target-missing"],
  [/^ANSWER requires a question filename$/, "answer.target-name"],
  [/^DATE must be an ISO date\/time/, "file.date"],
  [/^'utf-8' codec can't decode/, "file.utf8"],
  [/^Invalid UTF-8/, "file.utf8"],
  [/^missing header separator$/, "file.separator"],
  [/^duplicate header /, "file.duplicate-header"],
  [/^missing header\(s\): /, "file.missing-headers"],
  [/^a replacement keeps the original's sub-thread headers: /, "repair.subthread-header"],
  [/^a replacement corrects or drops an invalid sub-thread header: /, "repair.subthread-header"],
  [/^orphaned sub-thread: root \S+ is missing$/, "orphan.root-missing"],
  [/^orphaned sub-thread: root \S+ is quarantined by a repair record$/, "orphan.root-quarantined"],
  [/^orphaned sub-thread: root \S+ cannot be read as a message$/, "orphan.root-unreadable"],
  [/^(--root )?\S+ is quarantined by a repair record; promote a valid root instead$/, "promote.root-quarantined"],
  [/^(--root )?\S+ is not a valid message: /, "promote.root-invalid"],
  [/^unknown sender, status, or language$/, "file.sender-status-language"],
  [/^PROMOTED-FROM: \S+ is earlier in T\d+, so this is no longer the topic's first message/, "promoted.displaced"],
  [/^sub-thread message sorts before its root \S+ in posting order$/, "member.before-root"],
];
const PARSE = new Set(["file.separator", "file.utf8", "file.duplicate-header", "file.missing-headers"]);
function rule(text, headers = {}) {
  const other = text.match(/^rooms\/[^/]+\/([^/:]+\.txt): (.*)$/);
  if (other) {
    const [, name, inner] = other, parse = PARSE.has(rule(inner));
    if (headers["PROMOTED-FROM"] === name && parse) return "promoted.origin-unreadable";
    if (headers.SUBTHREAD === name) return parse ? "subthread.root-unreadable" : "subthread.root-invalid";
    return "unclassified: " + text;
  }
  for (const [re, id] of RULES) if (re.test(text)) return id;
  return "unclassified: " + text;
}
// The rules whose text the viewer reproduces word for word (AC2 amendment).
const EXACT = id => /^(subthread|also|state|promoted|member|orphan|repair|reply-to|answer)\./.test(id) || id === "file.separator" || id === "file.duplicate-header" || id === "file.missing-headers" || id === "file.date" || id === "file.sender-status-language";
const EXACT_POST = id => EXACT(id) && !["member.before-root", "subthread.root-ineligible"].includes(id);

let browser, template;
before(async () => {
  browser = await h.launch();
  // One fresh canonical board (boardctl init, both participants joined), copied for every case.
  template = h.path.join(h.tmpDir("afb-shared-fixture-"), "project");
  for (const args of [["init", template, "--project-id", "subs", "--project-name", "Subs"], ...DATA.board.participants.map(who => ["join", who, "--path", template])]) {
    const r = h.boardctl(args); assert.equal(r.code, 0, args.join(" ") + ": " + r.err);
  }
});
after(async () => { await browser.close(); h.fs.rmSync(h.path.dirname(template), { recursive: true, force: true }); });

// Writes a case's files into a copy of the template; message files get increasing modification times in `order`.
function boardFor(files, order) {
  const proj = h.path.join(h.tmpDir("afb-shared-case-"), "project"), base = h.path.join(proj, ".agent-board"), room = h.path.join(base, "rooms", ROOM);
  h.fs.cpSync(template, proj, { recursive: true }); h.fs.mkdirSync(room, { recursive: true });
  const bytes = f => f.base64 !== undefined ? Buffer.from(f.base64, "base64") : Buffer.from(f.text, "utf8");
  const messages = files.filter(f => !f.name.includes("/") && f.name.endsWith(".txt") && f.name !== "time-corrections.txt");
  for (const f of files.filter(f => !messages.includes(f))) { const p = h.path.join(base, f.name); h.fs.mkdirSync(h.path.dirname(p), { recursive: true }); h.fs.writeFileSync(p, bytes(f)); }
  const names = order || messages.map(f => f.name);
  assert.deepEqual([...names].sort(), messages.map(f => f.name).sort(), "an arrival order lists every message");
  names.forEach((name, i) => { const p = h.path.join(room, name); h.fs.writeFileSync(p, bytes(messages.find(f => f.name === name))); const t = new Date(Date.UTC(2026, 10, 3, 12, 0, i)); h.fs.utimesSync(p, t, t); });
  return proj;
}
async function open(proj) {
  const s = await h.openPage(browser);
  const errors = []; s.page.on("pageerror", e => errors.push(e.message));
  await s.page.setInputFiles("#fallback", proj);
  await s.page.waitForFunction(() => { const m = window.__boardTest.getModel(); return m && Array.isArray(m.repairs) && Array.isArray(m.repairErrors); });
  return { ...s, errors };
}
// What the viewer reports, in the fixture's vocabulary.
const VIEW = room => {
  const msgs = B.msgs.filter(m => m.scope === "room" && m.dir === room);
  // `validate` skips a file withdrawn by a repair record: no error, valid in the fixture's sense, never listed.
  const files = Object.fromEntries(msgs.map(m => [m.file, { valid: !m.metadataError || !!m.quarantined, error: m.quarantined ? null : m.validationError || null, headers: { ...m.h } }]));
  const warnings = msgs.filter(m => subthreadWarning(m)).sort((a, b) => a.path < b.path ? -1 : 1).map(m => ({ file: m.path, text: m.path + ": " + subthreadWarning(m) }));
  const listed = msgs.filter(m => !m.metadataError && !m.quarantined && signingEligible(m) && !m.receipt);
  const subthreads = [...subthreadsOf().values()].filter(x => x.dir === room && subthreadMembers(x).length).map(x => {
    const members = subthreadMembers(x);
    return { root: x.root, state: subthreadState(x).state, replies: members.length, participants: [...new Set(members.map(m => m.author))].sort() };
  }).sort((a, b) => a.root < b.root ? -1 : 1);
  return { files, warnings, otherErrors: B.repairErrors.map(text => ({ file: text.slice(0, text.indexOf(": ")), text })),
    orphans: msgs.filter(m => subthreadWarning(m).startsWith("orphaned sub-thread")).map(m => m.file).sort(),
    membership: Object.fromEntries(listed.map(m => [m.file, m.subthread || null])), listed: listed.map(m => m.file).sort(),
    mainFlow: listed.filter(m => !m.subthread || m.subthreadAlso).map(m => m.file).sort(), subthreads };
};

function compareCase(c, v, where) {
  const e = c.expect, tag = `${c.id}${where}`;
  // Files: verdict and rule for every file; exact text for the exact rules.
  assert.deepEqual(Object.keys(v.files).sort(), Object.keys(e.files).sort(), `${tag}: the same message files`);
  for (const [name, want] of Object.entries(e.files)) {
    const got = v.files[name], id = got.error ? rule(got.error, got.headers) : null;
    assert.equal(got.valid, want.valid, `${tag}: ${name} verdict (viewer error: ${got.error})`);
    assert.equal(id, want.rule, `${tag}: ${name} rule (viewer: ${got.error}; canonical: ${want.error})`);
    if (want.rule && EXACT(want.rule)) assert.equal(got.error, want.error, `${tag}: ${name} text`);
  }
  assert.deepEqual(v.warnings.map(w => ({ file: w.file, rule: rule(w.text.slice(w.file.length + 2)), text: w.text })), e.warnings.map(w => ({ file: w.file, rule: w.rule, text: w.text })), `${tag}: warnings`);
  assert.deepEqual(v.otherErrors.map(o => ({ file: o.file, rule: rule(o.text.slice(o.file.length + 2)), text: o.text })), e.otherErrors.map(o => ({ file: o.file, rule: o.rule, text: o.text })), `${tag}: other errors`);
  assert.deepEqual(v.orphans, [...e.orphans].sort(), `${tag}: orphans`);
  assert.deepEqual(Object.fromEntries(Object.entries(v.membership).sort()), Object.fromEntries(Object.entries(e.membership).sort()), `${tag}: membership`);
  assert.deepEqual(v.listed, [...e.listed].sort(), `${tag}: listed`);
  assert.deepEqual(v.mainFlow, [...e.mainFlow].sort(), `${tag}: main flow`);
  assert.deepEqual(v.subthreads, e.subthreads, `${tag}: sub-thread state, replies and participants`);
}

test("AC2 the fixture is the pinned canonical one and covers the S4 arrival and tie cases and the S5 concurrent writers", () => {
  const convention = h.fs.readFileSync(h.path.join(h.VENDOR, ".agent-board", "CONVENTION.md"), "utf8").match(/^Version: (\S+)$/m)[1];
  assert.equal(DATA.version, 1); assert.equal(DATA.convention, convention);
  const ids = DATA.cases.map(c => c.id);
  for (const id of ["state-posting-order", "tie-only", "concurrent-writers", "promoted-first-is-a-warning"]) assert.ok(ids.includes(id), id);
  for (const id of ["state-posting-order", "tie-only", "concurrent-writers"]) assert.ok(DATA.cases.find(c => c.id === id).arrivals.length >= 2, id + " has arrival orders");
  assert.ok(DATA.cases.length >= 21 && DATA.posts.length >= 13);
});

for (const c of DATA.cases) {
  test(`AC2 case ${c.id} (audit ${c.auditRows.join(", ")}; ${c.property})`, async () => {
    for (const [i, order] of [[null, null], ...(c.arrivals || []).map((o, i) => [i, o])]) {
      const proj = boardFor(c.files, order), s = await open(proj);
      try {
        compareCase(c, await s.page.evaluate(VIEW, ROOM), i === null ? "" : ` (arrival order ${i + 1})`);
        assert.deepEqual(s.errors, [], "no page errors");
      } finally { await s.ctx.close(); h.fs.rmSync(h.path.dirname(proj), { recursive: true, force: true }); }
    }
  });
}

// A post or promote, run through the viewer's own writer: composeMessage (every viewer writer composes through it)
// with the argv's options, or the pane's Promote. Nothing is delivered: the comparison is refuse/accept and its words.
async function runPost(page, argv) {
  const arg = k => { const i = argv.indexOf(k); return i < 0 ? undefined : argv[i + 1]; };
  return page.evaluate(async ({ command, o, root, title }) => {
    const reason = e => String(e && e.message || e).replace(/^Cannot post in this sub-thread: /, "");
    if (command === "promote") {
      openSubthread("room:" + o.room + "|" + root);
      try { await subPromote(title); return { exit: 0, error: null }; } catch (e) { return { exit: 2, error: reason(e) }; }
    }
    const source = o.replyTo && o.replyTo !== "-" ? B.messageIndex.get("room:" + o.room + "|" + o.replyTo) : null;
    // Answers follow their question, as every viewer answer writer stamps subthreadOf(source).
    if (o.answer && !o.subthread) o.subthread = subthreadOf(source) || undefined;
    if (o.subthread && !o.replyTo) o.replyTo = o.subthread;
    try { const msg = composeMessage({ ...o, confirmedAgent: true }); return { exit: 0, error: null, text: msg.text }; }
    catch (e) { return { exit: 2, error: reason(e) }; }
  }, { command: argv[0], root: arg("--root"), title: arg("--title"),
    o: { sender: arg("--from"), to: arg("--to") || "all", scope: "room", room: arg("--room"), tid: arg("--thread"), slug: arg("--slug"), body: arg("--body"),
      status: arg("--status") || "INFO", replyTo: arg("--reply-to"), subthread: arg("--subthread"), subthreadState: arg("--subthread-state"), subthreadAlso: argv.includes("--also-main"),
      promotedFrom: arg("--promoted-from"), at: arg("--at"), answer: argv.includes("--answer-file") ? { question: "go", selected: ["yes"] } : undefined } });
}
for (const p of DATA.posts) {
  test(`AC2 post ${p.id} (audit ${p.auditRows.join(", ")})`, async () => {
    const proj = boardFor(p.files), s = await open(proj);
    try {
      const got = await runPost(s.page, p.argv), headers = Object.fromEntries((got.text || "").split("\n---\n")[0].split("\n").filter(Boolean).map(l => [l.slice(0, l.indexOf(": ")), l.slice(l.indexOf(": ") + 2)]));
      const id = got.error ? rule(got.error, { SUBTHREAD: (p.argv.includes("--subthread") ? p.argv[p.argv.indexOf("--subthread") + 1] : undefined), "PROMOTED-FROM": headers["PROMOTED-FROM"] }) : null;
      assert.equal(got.exit, p.exit, `${p.id}: refused or accepted (viewer: ${got.error})`);
      assert.equal(id, p.rule, `${p.id}: rule (viewer: ${got.error}; canonical: ${p.error})`);
      if (p.rule && EXACT_POST(p.rule)) assert.equal(got.error, p.error, `${p.id}: text`);
      if (p.written) for (const [k, v] of Object.entries(p.written)) assert.equal(headers[k], v, `${p.id}: written ${k}`);
      assert.deepEqual(s.errors, [], "no page errors");
    } finally { await s.ctx.close(); h.fs.rmSync(h.path.dirname(proj), { recursive: true, force: true }); }
  });
}
